<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import LionIcon from './LionIcon.vue'
import {onAuthStateChanged} from 'firebase/auth'
import {getStagingClients} from '../integrations/firebase/stagingClient'
import {mayWriteLive} from '../integrations/firebase/stagingConfig'
import {stagingSession} from '../integrations/firebase/stagingSession'
import {watchSupportTickets,watchSupportReplies,watchSupportTicket,createTicket,replyTicket,changeTicketStatus,changeTicketPriority,type Ticket,type Reply,type TicketPriority} from '../integrations/firestore/platform'
import {LIONFIT_CONTACT_EMAIL,LIONFIT_CONTACT_MAILTO} from '../features/platform/contact'
import {accountKey,ticketStateLabel,ticketStates,type TicketState} from '../features/platform/platformModel'
import {filterSupport,unread,safeSeen,priorityLabels} from '../features/platform/supportModel'
const p=withDefaults(defineProps<{platform?:boolean;visible?:boolean;dedicated?:boolean;gymNames?:Record<string,string>}>(),{visible:true})
const emit=defineEmits<{unread:[number];exit:[]}>()
const rows=ref<Ticket[]>([]),selected=ref<Ticket|null>(null),replies=ref<Reply[]>([]),busy=ref(false),error=ref(''),ready=ref(false),more=ref(false),replyMore=ref(false),legacy=ref(false),conversationReady=ref(false)
const type=ref('problema'),subject=ref(''),text=ref(''),reply=ref(''),sent=ref(false),compose=ref(false),search=ref(''),filter=ref('all'),seen=ref<Record<string,number>>({})
// Extra states/priority only after the reviewed rule update is enabled explicitly in local build config.
const advanced=import.meta.env.VITE_LIONFIT_SUPPORT_ADVANCED==='true'
const states=computed(()=>ticketStates.filter(s=>advanced||s!=='closed'))
const filtered=computed(()=>filterSupport(rows.value,search.value,filter.value,!!p.platform,seen.value,p.gymNames))
const unreadCount=computed(()=>rows.value.filter(t=>unread(t,!!p.platform,seen.value)).length)
watch(unreadCount,n=>emit('unread',n),{immediate:true})
const messageList=ref<HTMLElement|null>(null)
const pendingNewId=ref(''),heading=ref<HTMLElement|null>(null)
const canSend=computed(()=>conversationReady.value&&!busy.value&&mayWriteLive()&&reply.value.trim().length>=2)
const emptyMessage=computed(()=>rows.value.length?'Nessuna richiesta trovata.':'Non hai ancora conversazioni.')
function focusHeading(){void nextTick(()=>heading.value?.focus({preventScroll:true}))}
function back(){if(busy.value&&(selected.value||compose.value))return;if(selected.value){close();focusHeading();return}if(compose.value){compose.value=false;focusHeading();return}if(p.dedicated)emit('exit')}
function localBack(e:Event){if(!p.visible||(!p.dedicated&&!selected.value))return;e.preventDefault();back()}
function openNew(){const t=rows.value.find(t=>t.id===pendingNewId.value);if(t&&!selected.value&&!compose.value&&p.visible){pendingNewId.value='';void open(t)}}
watch(rows,openNew)
watch(pendingNewId,openNew)
const counts=computed(()=>({active:rows.value.filter(t=>['open','working'].includes(t.status)).length,resolved:rows.value.filter(t=>['resolved','closed'].includes(t.status)).length}))
let listSize=40,replySize=50,queryEpoch=0,messageEpoch=0,epoch=0,detailEpoch=0,alive=true,scope='',stopAuth:(()=>void)|undefined,stopTicket:(()=>void)|undefined
let listStops:(()=>void)[]=[],replyStops:(()=>void)[]=[]
const clear=(arr:(()=>void)[])=>arr.splice(0).forEach(f=>f())
const current=(n:number)=>alive&&n===epoch
const report=(n:number,e:unknown)=>{if(current(n))error.value=e instanceof Error?e.message:'Operazione non riuscita.'}
function close(){detailEpoch++;stopTicket?.();stopTicket=undefined;clear(replyStops);messageEpoch++;replySize=50;selected.value=null;replies.value=[];reply.value='';conversationReady.value=false;replyMore.value=false;}
function reset(){epoch++;clear(listStops);close();queryEpoch++;listSize=40;rows.value=[];ready.value=false;busy.value=false;more.value=false;legacy.value=false;seen.value={};scope='';pendingNewId.value='';error.value='';subject.value='';text.value='';sent.value=false;compose.value=false;search.value='';filter.value='all'}
function mark(){const t=selected.value;if(!t||!p.visible||document.hidden||!conversationReady.value||!scope)return;const at=Math.max(p.platform?t.createdAt:0,...replies.value.filter(r=>r.author===(p.platform?'requester':'platform')).map(r=>r.createdAt));if(at<=(seen.value[t.id]||0))return;seen.value=safeSeen({...seen.value,[t.id]:at});try{localStorage.setItem(scope,JSON.stringify(seen.value))}catch{/* optional */}}
watch(()=>p.visible,v=>{if(v)mark();else close()})
async function load(append=false){if(busy.value||!scope)return;const n=epoch,q=++queryEpoch;busy.value=true;error.value='';if(append)listSize+=40;else listSize=40;clear(listStops);try{const stop=await watchSupportTickets(!!p.platform,r=>{if(!current(n)||q!==queryEpoch)return;rows.value=r.rows;more.value=r.more;legacy.value=r.legacy;ready.value=true;busy.value=false},e=>{if(current(n)&&q===queryEpoch){report(n,e);busy.value=false}},listSize,legacy.value);if(!current(n)||q!==queryEpoch)stop();else listStops.push(stop)}catch(e){if(current(n)&&q===queryEpoch){report(n,e);busy.value=false}}}
async function open(t:Ticket){pendingNewId.value='';close();selected.value=t;compose.value=false;sent.value=false;error.value='';focusHeading();const n=epoch,d=detailEpoch;try{const stop=await watchSupportTicket(t.id,!!p.platform,v=>{if(!current(n)||d!==detailEpoch)return;if(!v){close();return}selected.value=v;mark()},e=>{if(current(n)&&d===detailEpoch){report(n,e);close()}});if(!current(n)||d!==detailEpoch){stop();return}stopTicket=stop;await messages()}catch(e){report(n,e)}}
async function messages(append=false){const t=selected.value;if(!t||(append&&!replyMore.value))return;const n=epoch,d=detailEpoch,q=++messageEpoch;if(append){replyMore.value=false;replySize+=50}clear(replyStops);let first=true;try{const stop=await watchSupportReplies(t.id,!!p.platform,r=>{if(!current(n)||d!==detailEpoch||q!==messageEpoch)return;const el=messageList.value,nearEnd=!el||el.scrollHeight-el.scrollTop-el.clientHeight<100;const oldHeight=el?.scrollHeight||0,isOlder=append&&first,isInitial=first&&!append;first=false;replies.value=r.rows.sort((a,b)=>a.createdAt-b.createdAt||a.id.localeCompare(b.id));replyMore.value=r.more;conversationReady.value=true;mark();void nextTick(()=>{const el=messageList.value;if(!el)return;if(isOlder)el.scrollTop+=el.scrollHeight-oldHeight;else if(isInitial||nearEnd)el.scrollTop=el.scrollHeight})},e=>{if(current(n)&&d===detailEpoch&&q===messageEpoch){report(n,e);replyMore.value=append}},replySize);if(!current(n)||d!==detailEpoch||q!==messageEpoch)stop();else replyStops.push(stop)}catch(e){if(current(n)&&d===detailEpoch&&q===messageEpoch){report(n,e);replyMore.value=append}}}
async function action(fn:()=>Promise<void>){if(busy.value)return;const n=epoch;busy.value=true;error.value='';try{await fn()}catch(e){report(n,e)}finally{if(current(n))busy.value=false}}
function submit(){const n=epoch;return action(async()=>{const id=await createTicket(type.value,subject.value,text.value,accountKey(stagingSession.value));if(current(n)){text.value='';subject.value='';compose.value=false;search.value='';filter.value='all';sent.value=true;pendingNewId.value=id}})}
function send(){const t=selected.value,n=epoch,d=detailEpoch,msg=reply.value;if(t&&canSend.value)return action(async()=>{await replyTicket(t.id,!!p.platform,msg);if(current(n)&&d===detailEpoch&&reply.value===msg){reply.value='';void nextTick(()=>{const el=messageList.value;if(el)el.scrollTop=el.scrollHeight})}})}
function update(value:TicketState){const t=selected.value;if(t)return action(()=>changeTicketStatus(t.id,value))}
function priority(value:TicketPriority){const t=selected.value;if(t)return action(()=>changeTicketPriority(t.id,value))}
function begin(){const auth=getStagingClients().auth,u=auth.currentUser,s=stagingSession.value;const identity=p.platform?u?.uid:(s?.uid===u?.uid?accountKey(s):'');const key=identity?`lf-support-seen-v1:${auth.app.options.projectId}:${p.platform?'control':'member'}:${identity}`:'';if(scope===key)return;reset();if(!key)return;scope=key;try{seen.value=safeSeen(JSON.parse(localStorage.getItem(scope)||'{}'))}catch{/* optional */}void load()}
watch(()=>accountKey(stagingSession.value),begin)
onMounted(()=>{window.addEventListener('lionfit:local-back',localBack);document.addEventListener('visibilitychange',mark);stopAuth=onAuthStateChanged(getStagingClients().auth,begin);begin()});onUnmounted(()=>{window.removeEventListener('lionfit:local-back',localBack);document.removeEventListener('visibilitychange',mark);alive=false;stopAuth?.();reset()})
const time=(v:number)=>v?new Date(v).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}):''
const day=(v:number)=>v?new Date(v).toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'}):''
const sameDay=(a:number,b:number)=>day(a)===day(b)
const fmt=(v:number)=>v?new Date(v).toLocaleString('it-IT',{dateStyle:'short',timeStyle:'short'}):''
</script>
<template>
<section class="lf29-support" :class="{'panel':!dedicated,'lf29-dedicated':dedicated,'lf29-has-chat':!!selected}">
 <header v-if="!selected" class="lf29-header">
  <button v-if="dedicated" class="lf29-back" type="button" aria-label="Torna indietro" @click="back"><LionIcon name="back" :size="24"/></button>
  <div class="lf29-heading"><h2 ref="heading" tabindex="-1">{{compose?'Nuova richiesta':platform?'Assistenza LionFit':'Assistenza'}}</h2><span v-if="!compose&&unreadCount" class="lf29-unread-count">{{unreadCount}} non lette</span></div>
  <button v-if="!platform&&!compose" type="button" class="primary lf29-new" @click="pendingNewId='';compose=true;sent=false;focusHeading()"><LionIcon name="plus" :size="18"/> Nuova</button>
  <button v-if="compose&&!dedicated" type="button" class="secondary" @click="back">Annulla</button>
 </header>
 <p v-if="error" role="alert" class="notice lf29-error">{{error}} <button v-if="!selected" class="secondary" @click="load()">Riprova</button><button v-else-if="!conversationReady" class="secondary" @click="open(selected)">Riprova</button></p>
 <p v-if="sent&&!selected" role="status" class="notice">Richiesta inviata.</p>
 <form v-if="compose&&!platform" class="lf29-compose stack" @submit.prevent="submit"><label>Tipo<select v-model="type"><option value="problema">Problema</option><option value="suggerimento">Suggerimento</option><option value="account">Account</option><option value="altro">Altro</option></select></label><label>Oggetto<input v-model="subject" required maxlength="100"/></label><label>Messaggio<textarea v-model="text" required minlength="2" maxlength="1800" rows="5"/></label><small class="muted">Non inserire password o dati sanitari.</small><button class="primary" :disabled="busy||!mayWriteLive()">Invia richiesta</button></form>
 <div v-else-if="!selected" class="lf29-list">
  <div v-if="platform" class="lf29-kpis"><button class="secondary" @click="filter='unread'"><strong>{{unreadCount}}</strong> Non lette</button><button class="secondary" @click="filter='active'"><strong>{{counts.active}}</strong> Aperte</button><button class="secondary" @click="filter='resolved'"><strong>{{counts.resolved}}</strong> Risolte/chiuse</button></div>
  <div class="lf29-filters"><input v-model="search" type="search" aria-label="Cerca richieste" placeholder="Cerca conversazioni…"/><select v-model="filter" aria-label="Filtra richieste"><option value="all">Tutte</option><option value="unread">Non lette</option><option value="active">Aperte / in lavorazione</option><option value="resolved">Risolte</option><option v-if="advanced" value="closed">Chiuse</option></select></div>
  <p v-if="!ready&&!error" class="muted" role="status">Caricamento…</p><div v-else-if="ready&&!filtered.length" class="lf29-empty"><LionIcon name="team" :size="42"/><p>{{emptyMessage}}</p><button v-if="!rows.length&&!platform" class="primary" @click="pendingNewId='';compose=true;focusHeading()">Scrivi all’assistenza</button></div>
  <button v-for="t in filtered" :key="t.id" type="button" class="lf29-row" @click="open(t)"><span class="lf29-avatar"><LionIcon :name="platform?'user':'team'" :size="24"/></span><span class="lf29-row-body"><strong>{{t.subject}}</strong><small>{{platform?t.requesterName+' · '+(gymNames?.[t.gymId]||t.gymId):'Assistenza LionFit'}}</small><span class="lf29-preview">{{t.message}}</span></span><span class="lf29-row-meta"><small>{{fmt(t.updatedAt||t.createdAt)}}</small><span>{{ticketStateLabel(t.status)}}</span><small v-if="t.priority==='high'">Priorità alta</small><i v-if="unread(t,!!platform,seen)" class="lf29-dot" aria-label="Non letta"/></span></button>
  <button v-if="more" class="secondary" :disabled="busy" @click="load(true)">Carica altre richieste</button><small v-if="platform&&more" class="muted">Conteggi e ricerca sulle richieste caricate.</small><small v-if="legacy" class="muted">Ordinamento per data di apertura.</small>
  <a v-if="!platform" class="lf29-contact" :href="LIONFIT_CONTACT_MAILTO">{{LIONFIT_CONTACT_EMAIL}}</a>
 </div>
 <article v-else class="lf29-chat">
  <header class="lf29-header lf29-chat-head"><button class="lf29-back" type="button" aria-label="Torna alle conversazioni" @click="back"><LionIcon name="back" :size="24"/></button><span class="lf29-avatar"><LionIcon :name="platform?'user':'team'" :size="24"/></span><div class="lf29-heading"><h3 ref="heading" tabindex="-1">{{selected.subject}}</h3><small>{{platform?selected.requesterName+' · '+(gymNames?.[selected.gymId]||selected.gymId):'Assistenza LionFit'}} · {{ticketStateLabel(selected.status)}}</small></div></header>
  <div v-if="platform" class="lf29-filters lf29-admin"><label>Stato<select :value="selected.status" :disabled="busy||!mayWriteLive()" @change="update(($event.target as HTMLSelectElement).value as TicketState)"><option v-for="s in states" :key="s" :value="s">{{ticketStateLabel(s)}}</option></select></label><label v-if="advanced">Priorità<select :value="selected.priority" :disabled="busy||!mayWriteLive()" @change="priority(($event.target as HTMLSelectElement).value as TicketPriority)"><option v-for="(label,key) in priorityLabels" :key="key" :value="key">{{label}}</option></select></label></div>
  <div ref="messageList" class="lf29-messages" role="log" aria-label="Conversazione" aria-relevant="additions text">
   <button v-if="replyMore" class="secondary lf29-older" type="button" @click="messages(true)">Messaggi precedenti</button>
   <template v-if="!replyMore"><div class="lf29-day">{{day(selected.createdAt)}}</div><div class="lf29-bubble" :class="{'is-own':!platform}"><p>{{selected.message}}</p><small>{{time(selected.createdAt)}}</small></div></template>
   <p v-if="!conversationReady" role="status" class="muted">Caricamento messaggi…</p>
   <template v-for="(r,i) in replies" :key="r.id"><div v-if="i===0?!sameDay(r.createdAt,selected.createdAt)||replyMore:!sameDay(r.createdAt,replies[i-1].createdAt)" class="lf29-day">{{day(r.createdAt)}}</div><div class="lf29-bubble" :class="{'is-own':r.author===(platform?'platform':'requester')}"><p>{{r.message}}</p><small>{{time(r.createdAt)}}</small></div></template>
  </div>
  <form v-if="!['resolved','closed'].includes(selected.status)" class="lf29-composer" @submit.prevent="send"><textarea v-model="reply" aria-label="Messaggio" required minlength="2" maxlength="1800" rows="2" placeholder="Scrivi un messaggio…" :disabled="!mayWriteLive()"/><button class="lf29-send primary" type="submit" :disabled="!canSend" aria-label="Invia messaggio"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M22 2 7 11l5 2 2 5 8-16ZM22 2 12 13"/></svg></button></form>
  <div v-else class="lf29-closed">{{selected.status==='closed'?'Conversazione chiusa':'Richiesta risolta'}}</div>
 </article>
</section>
</template>
<style scoped>
.lf29-support{display:flex;flex-direction:column;min-width:0;gap:12px}.lf29-support :is(h2,h3,p){margin:0}.lf29-support button{cursor:pointer}.lf29-dedicated{flex:1;min-height:0;overflow:hidden;gap:0;padding:0!important;background:var(--panel,var(--card,#17212b));color:var(--text);border:0!important;border-radius:0!important;box-shadow:none!important}.lf29-header{display:flex;align-items:center;min-width:0;gap:10px;padding:12px 10px;border-bottom:1px solid var(--border);flex-shrink:0}.lf29-dedicated>.lf29-header{padding-top:max(12px,env(safe-area-inset-top,0px))}.lf29-heading{flex:1;min-width:0;overflow-wrap:anywhere}.lf29-heading h2{font-size:1.3rem}.lf29-heading h3{font-size:1.05rem}.lf29-heading small,.lf29-unread-count{font-size:.8rem;color:var(--muted)}.lf29-back,.lf29-send{display:grid!important;place-items:center;flex:none;width:44px;height:44px;min-width:44px;padding:0!important;border-radius:50%!important}.lf29-back{background:transparent;border:0;color:var(--text)}.lf29-new{display:flex;align-items:center;justify-content:center;gap:5px;min-height:44px;white-space:nowrap}.lf29-list,.lf29-compose{display:flex;flex-direction:column;gap:10px;min-width:0;padding:12px}.lf29-dedicated>.lf29-list,.lf29-dedicated>.lf29-compose{flex:1;min-height:0;overflow:auto;padding-bottom:max(16px,env(safe-area-inset-bottom,0px))}.lf29-compose label{display:grid;gap:6px}.lf29-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.lf29-kpis button{display:grid;gap:3px;white-space:normal;font-size:.82rem;padding:10px 5px}.lf29-kpis strong{font-size:1.65rem}.lf29-filters{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:8px;align-items:end}.lf29-filters input,.lf29-filters select{width:100%;min-width:0}.lf29-row{display:flex!important;align-items:center;gap:10px;min-height:74px;width:100%;min-width:0;padding:12px 4px!important;background:transparent!important;color:var(--text)!important;border:0!important;border-bottom:1px solid var(--border)!important;border-radius:0!important;text-align:left;box-shadow:none!important}.lf29-avatar{flex:none;width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:#1c664c;color:#fff}.lf29-row-body{flex:1;min-width:0;display:grid;gap:4px}.lf29-row-body strong,.lf29-preview,.lf29-row-body small{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.lf29-row-body small,.lf29-preview,.lf29-row-meta{color:var(--muted);font-size:.78rem}.lf29-row-meta{flex:none;max-width:35%;display:grid;justify-items:end;text-align:right;gap:4px}.lf29-row-meta small{font-size:.72rem}.lf29-dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:#32c98a}.lf29-empty{padding:32px 12px;text-align:center;display:grid;justify-items:center;gap:14px;color:var(--muted)}.lf29-contact{margin-top:auto;text-align:center;font-size:.8rem;color:var(--muted);padding:12px}.lf29-chat{display:flex;flex-direction:column;min-width:0;min-height:0;gap:0;border:1px solid var(--border);border-radius:14px;overflow:hidden;height: min(680px,72vh)}.lf29-dedicated .lf29-chat{flex:1;height:auto;border:0;border-radius:0}.lf29-dedicated .lf29-chat-head{padding-top:max(12px,env(safe-area-inset-top,0px))}.lf29-admin{padding:8px 12px;flex-shrink:0}.lf29-admin label{font-size:.8rem}.lf29-messages{display:flex;flex-direction:column;gap:10px;flex:1;min-height:0;min-width:0;overflow:auto;overscroll-behavior:contain;padding:14px 12px;background:color-mix(in srgb,var(--panel,var(--card,#17212b)) 92%,#71877f)}.lf29-day{align-self:center;font-size:.72rem;color:var(--muted);padding:4px 8px}.lf29-older{align-self:center;flex-shrink:0}.lf29-bubble{flex:none;align-self:flex-start;width:fit-content;max-width:86%;min-width:68px;padding:10px 12px;border:1px solid var(--border);border-radius:14px 14px 14px 4px;overflow-wrap:anywhere;background:var(--card,var(--panel,#22323d));display:flex;flex-direction:column;gap:5px}.lf29-bubble p{white-space:pre-wrap;line-height:1.45}.lf29-bubble.is-own{align-self:flex-end;border-color:#267b59;border-radius:14px 14px 4px 14px;background:#165e43;color:#fff}.lf29-bubble small{color:var(--muted);font-size:.72rem;text-align:right}.lf29-bubble.is-own small{color:#ddf5e8}.lf29-composer{display:flex;flex:none;align-items:flex-end;gap:8px;border-top:1px solid var(--border);padding:10px 12px;background:var(--panel,var(--card,#17212b))}.lf29-dedicated .lf29-composer,.lf29-dedicated .lf29-closed{padding-bottom:max(12px,env(safe-area-inset-bottom,0px))}.lf29-composer textarea{flex:1;min-width:0;width:auto!important;min-height:44px;max-height:120px;padding:10px 13px!important;resize:vertical;border-radius:20px!important;font-size:16px;line-height:1.3}.lf29-send:disabled{opacity:.5}.lf29-closed{text-align:center;padding:12px;color:var(--muted);border-top:1px solid var(--border);flex:none}.lf29-error{margin:8px!important;flex-shrink:0;max-height:22vh;overflow:auto;overflow-wrap:anywhere}.lf29-heading :focus-visible{outline:2px solid #32c98a;outline-offset:3px}@media(max-width:390px){.lf29-avatar{width:38px;height:38px}.lf29-row{gap:7px}.lf29-row-meta{max-width:32%}.lf29-bubble{max-width:92%}.lf29-new{font-size:.85rem}.lf29-heading h3{font-size:1rem}}
</style>
